mapper.select:
SELECT t1.id, t2.id AS productId, t2.product_name AS productName, t2.image AS image, t2.price AS price, t2.stock AS stock, t2.browse AS browse, t2.ficti_browse AS fictiBrowse, t2.sales AS sales, t2.is_show AS productShowStatus, t2.is_seckill AS isSeckill, t2.activity AS activity, t1.status AS flashStatus, t1.flash_price AS flashPrice, t1.limit_per_user AS limitPerUser, t1.reserve_seconds AS reserveSeconds, t1.start_time AS startTime, t1.end_time AS endTime, CASE WHEN t1.status = 1 AND NOW() BETWEEN t1.start_time AND t1.end_time THEN 1 ELSE 0 END AS flashActive FROM shop_product t2 LEFT JOIN shop_flash_sale t1 ON t1.product_id = t2.id AND t1.is_del = 0 WHERE IFNULL(t2.is_del, 0) = 0
AND t2.product_name LIKE CONCAT('%', #{dto.productName}, '%')
AND t2.is_show = #{dto.productShowStatus}
AND IFNULL(t1.status, 0) = #{dto.flashStatus}
ORDER BY IFNULL(t1.sort, 0) DESC, t2.id DESC

SELECT 
FROM shop_flash_sale
WHERE product_id = #{productId}
  AND is_del = 0
  AND status = 1
  AND start_time <= #{now}
  AND end_time >= #{now}
LIMIT 1
